package com.jeshwin.crashlab;
import java.sql.*;import java.util.*;import java.util.concurrent.*;import org.apache.kafka.clients.admin.*;import org.apache.kafka.common.TopicPartition;
public final class M1Inspector {private M1Inspector(){} public static void main(String[]a)throws Exception{if(a.length!=4&&a.length!=6)throw new IllegalArgumentException("Usage: topic group account [event scope] label");String topic=a[0],group=a[1],account=a[2],event=a.length==6?a[3]:"",scope=a.length==6?a[4]:"",label=a.length==6?a[5]:a[3];long balance,dedup;try(var db=DatabaseWork.open();var q=db.prepareStatement("SELECT balance FROM accounts WHERE account_id=?");var d=db.prepareStatement("SELECT count(*) FROM processed_events WHERE handler_scope=? AND event_id=?")){q.setString(1,account);try(var r=q.executeQuery()){if(!r.next())throw new IllegalStateException("Missing account");balance=r.getLong(1);}d.setString(1,scope);d.setString(2,event);try(var r=d.executeQuery()){r.next();dedup=r.getLong(1);}}
Properties p=new Properties();p.put("bootstrap.servers",LabConfig.kafkaBootstrap());p.put("default.api.timeout.ms","15000");p.put("request.timeout.ms","10000");TopicPartition tp=new TopicPartition(topic,0);long start,end;Long committed;try(var admin=Admin.create(p)){start=admin.listOffsets(Map.of(tp,OffsetSpec.earliest())).partitionResult(tp).get(20,TimeUnit.SECONDS).offset();end=admin.listOffsets(Map.of(tp,OffsetSpec.latest())).partitionResult(tp).get(20,TimeUnit.SECONDS).offset();var os=admin.listConsumerGroupOffsets(group).partitionsToOffsetAndMetadata().get(20,TimeUnit.SECONDS);committed=os.containsKey(tp)?os.get(tp).offset():null;}System.out.println("{\"label\":\""+label+"\",\"balance\":"+balance+",\"dedupCount\":"+dedup+",\"startOffset\":"+start+",\"endOffset\":"+end+",\"committedOffset\":"+(committed==null?"null":committed)+"}");}}
